import java.util.HashMap;
import java.util.Map;

public class Solution {
    static class ContadorJanelas {
        private final long tamanhoMs;
        private final long graceMs;
        private final Map<String, Long> contagens = new HashMap<>();
        private long streamTime = Long.MIN_VALUE;
        private long descartados = 0;

        ContadorJanelas(long tamanhoMs, long graceMs) {
            if (tamanhoMs <= 0) throw new IllegalArgumentException("tamanho invalido");
            if (graceMs < 0) throw new IllegalArgumentException("grace invalido");
            this.tamanhoMs = tamanhoMs;
            this.graceMs = graceMs;
        }

        void registrar(long timestamp, String chave) {
            if (chave == null || chave.isBlank()) {
                throw new IllegalArgumentException("chave obrigatoria");
            }
            long inicio = Math.floorDiv(timestamp, tamanhoMs) * tamanhoMs;
            long fim = inicio + tamanhoMs;
            boolean atrasado = streamTime != Long.MIN_VALUE && fim + graceMs < streamTime;

            streamTime = Math.max(streamTime, timestamp);
            if (atrasado) {
                descartados++;
                return;
            }
            String janela = chave + "@" + inicio;
            contagens.merge(janela, 1L, Long::sum);
        }

        Map<String, Long> resultado() { return Map.copyOf(contagens); }
        long descartados() { return descartados; }
    }
}

