import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.Map;

class SolutionTest {
    @Test void contaNaMesmaJanela() {
        var c = new Solution.ContadorJanelas(60_000, 30_000);
        c.registrar(10_000, "a");
        c.registrar(50_000, "a");
        assertEquals(Map.of("a@0", 2L), c.resultado());
        assertEquals(0, c.descartados());
    }

    @Test void chavesSeparadasNaMesmaJanela() {
        var c = new Solution.ContadorJanelas(60_000, 0);
        c.registrar(1_000, "a");
        c.registrar(2_000, "b");
        assertEquals(1, c.resultado().get("a@0"));
        assertEquals(1, c.resultado().get("b@0"));
    }

    @Test void atrasoDentroDoGraceEhAceito() {
        var c = new Solution.ContadorJanelas(60_000, 30_000);
        c.registrar(120_000, "a");
        c.registrar(61_000, "a"); // janela 60k, fim 120k, grace 150k >= stream 120k
        assertEquals(1, c.resultado().get("a@60000"));
        assertEquals(0, c.descartados());
    }

    @Test void atrasoAlemDoGraceEhDescartado() {
        var c = new Solution.ContadorJanelas(60_000, 30_000);
        c.registrar(130_000, "a");
        c.registrar(10_000, "a"); // fim 60k + grace 90k < 130k
        assertEquals(1, c.descartados());
        assertFalse(c.resultado().containsKey("a@0"));
    }

    @Test void streamTimeNaoRegride() {
        var c = new Solution.ContadorJanelas(60_000, 60_000);
        c.registrar(300_000, "a");
        c.registrar(10_000, "a");
        assertEquals(1, c.descartados());
        c.registrar(310_000, "b");
        assertEquals(2, c.resultado().size());
    }

    @Test void parametrosInvalidos() {
        assertThrows(IllegalArgumentException.class, () -> new Solution.ContadorJanelas(0, 0));
        assertThrows(IllegalArgumentException.class, () -> new Solution.ContadorJanelas(1000, -1));
    }
}
